#!/usr/bin/env node
// One-off v7.1 CHORUS merge helper — offline, no credits, no API calls.
//
// `game/moth-baked.mjs` is a generated artifact ("do not edit by hand") that both
// `feat/moth-pass3` and `feat/moth-audio` regenerated independently. This script
// unions the two variants deterministically instead of re-running the Moth API:
//
//   * every bucket key present on either side survives;
//   * provenance (keyed by job id) is unioned the same way;
//   * the reverb-space aliases are consolidated to one record per real space:
//       - `irs.openair` is dropped (byte-identical to `irs.open-air`);
//       - `irs.tunnel` prefers the audio branch's 3.5 s corridor IR;
//       - `hall`, `cathedral` (pass 3) and `void` (audio) are all kept.
//   * `irs`/`spaces`/`audio` values are refreshed afterwards by
//     `node scripts/moth-bake.mjs repair` from the committed raw files, which
//     also repairs the pass-3 records that were baked with the shallow-tap bug
//     (`taps: 0`).
//
// Usage: node scripts/merge-baked-variants.mjs <ours.mjs> <theirs.mjs> <out.mjs>

import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const [oursPath, theirsPath, outPath] = process.argv.slice(2);
if (!oursPath || !theirsPath || !outPath) {
  console.error('usage: node scripts/merge-baked-variants.mjs <ours.mjs> <theirs.mjs> <out.mjs>');
  process.exit(2);
}

async function loadModule(file) {
  const mod = await import(`${pathToFileURL(path.resolve(file)).href}?v=${Date.now()}`);
  if (!mod.MOTH_BAKED) throw new Error(`${file} does not export MOTH_BAKED`);
  return structuredClone(mod.MOTH_BAKED);
}

// Space consolidation decided in the v7.1 merge (see docs/MOTH.md).
const DROP = { irs: new Set(['openair']), provenance: new Set(['ir-openair']) };
const PREFER_THEIRS = { irs: new Set(['tunnel']), provenance: new Set(['ir-tunnel']) };
const BUCKETS = ['textures', 'normals', 'materials', 'sky', 'effects', 'levels', 'seeds', 'motifs', 'irs', 'audio', 'spaces', 'provenance'];

const ours = await loadModule(oursPath);
const theirs = await loadModule(theirsPath);
const merged = structuredClone(ours);

for (const bucket of BUCKETS) {
  const from = theirs[bucket];
  if (!from) continue;
  merged[bucket] ??= {};
  for (const [key, value] of Object.entries(from)) {
    if (merged[bucket][key] === undefined || PREFER_THEIRS[bucket]?.has(key)) merged[bucket][key] = value;
  }
  for (const key of DROP[bucket] || []) delete merged[bucket][key];
}

// Match writeModule(): drop null frame placeholders before serialising.
for (const effect of Object.values(merged.effects || {})) effect.frames = (effect.frames || []).filter(Boolean);

const header = '// GENERATED by scripts/moth-bake.mjs — do not edit by hand.\n'
  + '// Regenerate with: MOTH_API_KEY=... node scripts/moth-bake.mjs run\n'
  + '// Source engines: Moth Quantum Atlas (https://api.mothquantum.com).\n'
  + '// v7.1: union of the pass-3 and audio variants via scripts/merge-baked-variants.mjs\n'
  + '// (openair consolidated into open-air) then `moth-bake.mjs repair` (offline).\n\n';

fs.writeFileSync(outPath, `${header}export const MOTH_BAKED = ${JSON.stringify(merged, null, 2)};\n\nexport default MOTH_BAKED;\n`);
console.log(`merged ${path.relative(process.cwd(), oursPath)} + ${path.relative(process.cwd(), theirsPath)} -> ${path.relative(process.cwd(), outPath)}`);
